const setLanguage=(lang)=>{const t={...copy.en,...(copy[lang]||{}),...atelierCopy.en,...(atelierCopy[lang]||{}),...scrollCopy.en,...(scrollCopy[lang]||{})};document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=t[el.dataset.i18n]||el.innerHTML);document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t[el.dataset.i18nPlaceholder]||el.placeholder);document.title=`LitBuy Sheet | ${(t.heroTitle||copy.en.heroTitle).replace(/<[^>]*>/g,' ')}`;if(window.refreshAtelier)window.refreshAtelier();};
const select=document.querySelector('#language-select');if(select){const savedLanguage=localStorage.getItem('litbuy-sheet-language');const activeLanguage=copy[savedLanguage]?savedLanguage:'en';select.value=activeLanguage;setLanguage(activeLanguage);select.addEventListener('change',e=>{localStorage.setItem('litbuy-sheet-language',e.target.value);setLanguage(e.target.value);});}
document.querySelector('#search-form')?.addEventListener('submit',e=>{e.preventDefault();const q=document.querySelector('#site-search').value.trim();window.location.href=q?`https://findspreadsheet.com/search.html?keywords=${encodeURIComponent(q)}&channelid=2`:'https://findspreadsheet.com/AllProducts/'});

(()=>{const frame=document.querySelector('.atelier-frame');if(!frame)return;const items=[...document.querySelectorAll('.dial-item')],stageTitle=document.querySelector('#stage-title'),stageDescription=document.querySelector('#stage-description'),stageRoute=document.querySelector('#stage-route'),visual=document.querySelector('.stage-visual'),mediaCaption=document.querySelector('#media-caption'),mediaNumber=document.querySelector('#media-number'),points=[...document.querySelectorAll('.detail-point')];let active=0,view=0;const keyForView=i=>`atelierImage${i+1}`;const copyText=(key)=>{const lang=document.documentElement.lang||'en';return (atelierCopy[lang]&&atelierCopy[lang][key])||atelierCopy.en[key]};const choose=(next)=>{active=(next+items.length)%items.length;items.forEach((item,i)=>{const selected=i===active;item.classList.toggle('is-active',selected);item.setAttribute('aria-selected',String(selected));});const item=items[active],name=item.querySelector('b').textContent,description=item.querySelector('em').textContent;stageTitle.textContent=name;stageDescription.textContent=description;stageRoute.href=item.dataset.url;};const chooseView=(next)=>{view=next;visual.dataset.view=String(view);points.forEach((point,i)=>point.classList.toggle('is-active',i===view));mediaNumber.textContent=`0${view+1}`;mediaCaption.textContent=copyText(keyForView(view));};items.forEach((item,i)=>item.addEventListener('click',()=>choose(i)));points.forEach((point,i)=>point.addEventListener('click',()=>chooseView(i)));document.addEventListener('keydown',event=>{if(document.activeElement&&document.activeElement.matches('input,select'))return;if(event.key==='ArrowDown'){event.preventDefault();choose(active+1)}if(event.key==='ArrowUp'){event.preventDefault();choose(active-1)}});let wheelBusy=false;frame.querySelector('.dial-pane').addEventListener('wheel',event=>{if(innerWidth<=900)return;event.preventDefault();if(wheelBusy)return;wheelBusy=true;choose(active+(event.deltaY>0?1:-1));setTimeout(()=>wheelBusy=false,240)},{passive:false});document.querySelector('.fit-toggle')?.addEventListener('click',event=>{const button=event.currentTarget,panel=document.querySelector('.atelier-size'),open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));button.querySelector('b').textContent=open?'+':'−';panel.hidden=open});document.querySelectorAll('.drawer-toggle').forEach(button=>button.addEventListener('click',()=>{const panel=document.querySelector(`#${button.dataset.drawer}`),open=!panel.hidden;document.querySelectorAll('.atelier-drawer').forEach(drawer=>drawer.hidden=true);panel.hidden=open;button.querySelector('span').textContent=open?'+':'−'}));window.refreshAtelier=()=>{choose(active);chooseView(view)};choose(active);chooseView(view)})();
